import React from 'react';

function SavedNotes() {
  const keys = Object.keys(localStorage).filter((k) => k.startsWith('notes_'));

  return (
    <div className="saved-notes-page">
      <h2>All Saved Notes</h2>
      {keys.length === 0 ? (
        <p>No notes saved yet. Watch videos and add notes to view them here.</p>
      ) : (
        keys.map((key) => {
          const videoId = key.replace('notes_', '');
          const notes = JSON.parse(localStorage.getItem(key));
          return (
            <div key={key} className="note-card">
              <h4>Video ID: {videoId}</h4>
              <ul>
                {notes.map((note, index) => (
                  <li key={index}>{note}</li>
                ))}
              </ul>
            </div>
          );
        })
      )}
    </div>
  );
}

export default SavedNotes;
